//go:build linux
// +build linux

// Code generated by gen-gdrcopy from gdrapi.h. DO NOT EDIT.

package gdrcopy

import (
	"testing"
	"unsafe"
)

// The expectations in this file come from clang, asked for the record layout
// of gdrapi.h on:
//   - x86_64-unknown-linux-gnu
//   - aarch64-unknown-linux-gnu
//   - powerpc64le-unknown-linux-gnu
//
// The targets agreed; generation fails if they ever stop agreeing, because one
// Go struct cannot then describe all of them.
//
// These tests need no GPU, no gdrdrv and no libgdrapi.

func TestInfoSize(t *testing.T) {
	if got, want := unsafe.Sizeof(Info{}), uintptr(48); got != want {
		t.Errorf("unsafe.Sizeof(Info{}) = %d, C sizeof(gdr_info_v2_t) = %d", got, want)
	}
	if got, want := unsafe.Alignof(Info{}), uintptr(8); got != want {
		t.Errorf("unsafe.Alignof(Info{}) = %d, C alignof(gdr_info_v2_t) = %d", got, want)
	}
}

func TestInfoOffsets(t *testing.T) {
	var i Info
	for _, tt := range []struct {
		member string
		got    uintptr
		want   uintptr
	}{
		{"va", unsafe.Offsetof(i.Va), 0},
		{"mapped_size", unsafe.Offsetof(i.MappedSize), 8},
		{"page_size", unsafe.Offsetof(i.PageSize), 16},
		{"tm_cycles", unsafe.Offsetof(i.TmCycles), 24},
		{"cycles_per_ms", unsafe.Offsetof(i.CyclesPerMs), 32},
		{"mapped:1, wc_mapping:1", unsafe.Offsetof(i.bits), 36},
		{"mapping_type", unsafe.Offsetof(i.MappingType), 40},
	} {
		if tt.got != tt.want {
			t.Errorf("gdr_info_v2_t.%s: Go offset %d, C offset %d", tt.member, tt.got, tt.want)
		}
	}
}

func TestInfoMemberWidths(t *testing.T) {
	var i Info
	for _, tt := range []struct {
		member string
		got    uintptr
		want   uintptr
	}{
		{"va", unsafe.Sizeof(i.Va), 8},
		{"mapped_size", unsafe.Sizeof(i.MappedSize), 8},
		{"page_size", unsafe.Sizeof(i.PageSize), 4},
		{"tm_cycles", unsafe.Sizeof(i.TmCycles), 8},
		{"cycles_per_ms", unsafe.Sizeof(i.CyclesPerMs), 4},
		{"bitfield storage unit", unsafe.Sizeof(i.bits), 4},
		{"mapping_type", unsafe.Sizeof(i.MappingType), 4},
	} {
		if tt.got != tt.want {
			t.Errorf("gdr_info_v2_t.%s: Go width %d, C width %d", tt.member, tt.got, tt.want)
		}
	}
}

// TestInfoBitfields checks the accessors against the measured position of each
// bitfield, by writing the raw bytes of an Info directly. gdr_info_v2_t
// declares mapped and wc_mapping as one-bit fields, which Go cannot express,
// so this is the only part of the mirror that is not a plain field.
func TestInfoBitfields(t *testing.T) {
	for _, tt := range []struct {
		name       string
		byteOffset int
		bit        uint
		read       func(Info) bool
	}{
		{"mapped", 36, 0, Info.Mapped},
		{"wc_mapping", 36, 1, Info.WCMapping},
	} {
		var info Info
		raw := (*[48]byte)(unsafe.Pointer(&info))
		if tt.read(info) {
			t.Errorf("%s: reported set in a zero Info", tt.name)
		}
		raw[tt.byteOffset] |= 1 << tt.bit
		if !tt.read(info) {
			t.Errorf("%s: not reported after setting byte %d bit %d", tt.name, tt.byteOffset, tt.bit)
		}
		for _, other := range []struct {
			name string
			read func(Info) bool
		}{
			{"mapped", Info.Mapped},
			{"wc_mapping", Info.WCMapping},
		} {
			if other.name != tt.name && other.read(info) {
				t.Errorf("setting %s also set %s", tt.name, other.name)
			}
		}
	}
}

// TestMemHandleABI guards the one shortcut this binding takes: gdr_mh_t is a
// struct wrapping a single unsigned long, and MemHandle is the bare word,
// which is what the calling conventions on every supported platform pass in
// the same register. Generation fails if the struct grows a second member;
// this checks the width Go gives the scalar.
func TestMemHandleABI(t *testing.T) {
	if got, want := unsafe.Sizeof(MemHandle(0)), uintptr(8); got != want {
		t.Errorf("unsafe.Sizeof(MemHandle) = %d, C sizeof(gdr_mh_t) = %d", got, want)
	}
	if got, want := unsafe.Alignof(MemHandle(0)), uintptr(8); got != want {
		t.Errorf("unsafe.Alignof(MemHandle) = %d, C alignof(gdr_mh_t) = %d", got, want)
	}
}

// TestEnumWidths checks that each enum type is as wide as a C int, which is
// what the compiler chose for these enumerations: every enumerator fits in an
// int and none is negative or unsigned-only.
func TestEnumWidths(t *testing.T) {
	for _, tt := range []struct {
		name string
		got  uintptr
	}{
		{"gdr_pin_flags_t", unsafe.Sizeof(PinFlags(0))},
		{"gdr_mapping_type_t", unsafe.Sizeof(MappingType(0))},
		{"gdr_map_flags_t", unsafe.Sizeof(MapFlags(0))},
		{"gdr_attr_t", unsafe.Sizeof(Attr(0))},
	} {
		if tt.got != 4 {
			t.Errorf("unsafe.Sizeof(%s) = %d, C enum is 4 bytes", tt.name, tt.got)
		}
	}
}

// TestEnumValues pins each enumerator to the value in the pinned header.
func TestEnumValues(t *testing.T) {
	for _, tt := range []struct {
		name string
		got  int64
		want int64
	}{
		{"GDR_PIN_FLAG_DEFAULT", int64(PinFlagDefault), 0},
		{"GDR_PIN_FLAG_FORCE_PCIE", int64(PinFlagForcePcie), 1},
		{"GDR_MAPPING_TYPE_NONE", int64(MappingTypeNone), 0},
		{"GDR_MAPPING_TYPE_WC", int64(MappingTypeWc), 1},
		{"GDR_MAPPING_TYPE_CACHING", int64(MappingTypeCaching), 2},
		{"GDR_MAPPING_TYPE_DEVICE", int64(MappingTypeDevice), 3},
		{"GDR_MAP_FLAG_DEFAULT", int64(MapFlagDefault), 0},
		{"GDR_MAP_FLAG_REQ_WC_MAPPING", int64(MapFlagReqWcMapping), 1},
		{"GDR_MAP_FLAG_REQ_CACHE_MAPPING", int64(MapFlagReqCacheMapping), 2},
		{"GDR_MAP_FLAG_REQ_DEVICE_MAPPING", int64(MapFlagReqDeviceMapping), 3},
		{"GDR_ATTR_USE_PERSISTENT_MAPPING", int64(AttrUsePersistentMapping), 1},
		{"GDR_ATTR_SUPPORT_PIN_FLAG_FORCE_PCIE", int64(AttrSupportPinFlagForcePcie), 2},
		{"GDR_ATTR_USING_DMA_BUF_MMAP", int64(AttrUsingDmaBufMmap), 3},
	} {
		if tt.got != tt.want {
			t.Errorf("%s = %d, gdrapi.h says %d", tt.name, tt.got, tt.want)
		}
	}
}

// TestPageConstants checks the GPU page granularity against GPU_PAGE_SHIFT and
// the mask against the offset the header derives from it.
func TestPageConstants(t *testing.T) {
	if GPUPageShift != 16 {
		t.Errorf("GPUPageShift = %d, GPU_PAGE_SHIFT = 16", GPUPageShift)
	}
	if got, want := GPUPageSize, uintptr(65536); got != want {
		t.Errorf("GPUPageSize = %d, GPU_PAGE_SIZE = %d", got, want)
	}
	if got := uintptr(0xffff) &^ GPUPageMask; got != 65535 {
		t.Errorf("GPUPageMask leaves offset %d in an address one byte below a page boundary, want 65535", got)
	}
	if got := GPUPageSize &^ GPUPageMask; got != 0 {
		t.Errorf("GPUPageMask does not pass an aligned address unchanged: %d", got)
	}
}

// TestHeaderVersion checks the version constants against the pinned header.
// They describe the header these bindings were generated from, not whatever
// libgdrapi ends up loaded; RuntimeGetVersion reports that.
func TestHeaderVersion(t *testing.T) {
	if HeaderVersionMajor != 2 || HeaderVersionMinor != 6 {
		t.Errorf("header version %d.%d, gdrapi.h says 2.6", HeaderVersionMajor, HeaderVersionMinor)
	}
	if MinimumDriverVersionMajor != 2 || MinimumDriverVersionMinor != 0 {
		t.Errorf("minimum gdrdrv version %d.%d, gdrapi.h says 2.0", MinimumDriverVersionMajor, MinimumDriverVersionMinor)
	}
}
